17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Map;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.addressNormalizer = addressNormalizer;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	
119	        HttpStatus invalid = normalizeAndValidate(owner);
120	        if (invalid != null) {
121	            return new ResponseEntity<>(invalid);
122	        }
123	        if (isDailyLimitReached(owner.getRegistrationDate())) {
124	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
125	        }
126	
127	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
128	        assignHousehold(owner, sharesHousehold);
129	
130	        HttpStatus conflict = checkForConflicts(owner);
131	        if (conflict != null) {
132	            return new ResponseEntity<>(conflict);
133	        }
134	
135	        assignDerivedAttributes(owner);
136	        this.clinicService.saveOwner(owner);
137	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
138	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
139	        return created(owner);
140	    }
141	
142	    /**
143	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
144	     * rejected. The owner's address is normalized (a blank address is rejected), its telephone is
145	     * converted to E.164 (an unconvertible number is rejected), its postcode is checked against its
146	     * city's region, a registration date in the future is rejected, and the effective registration
147	     * date (the supplied one, or today when none was given) is rolled onto a business day and stored
148	     * back on the owner. Returns {@code null} once the owner is valid and normalized, or the
149	     * {@link HttpStatus} the create must fail with ({@code 400 Bad Request}) otherwise.
150	     */
151	    private HttpStatus normalizeAndValidate(Owner owner) {
152	        String address = addressNormalizer.normalize(owner.getAddress());
153	        if (address.isEmpty()) {
154	            return HttpStatus.BAD_REQUEST;
155	        }
156	        owner.setAddress(address);
157	        String telephone = toE164(owner.getTelephone());
158	        if (telephone == null) {
159	            return HttpStatus.BAD_REQUEST;
160	        }
161	        owner.setTelephone(telephone);
162	        if (!owner.isPostcodeValid()) {
163	            return HttpStatus.BAD_REQUEST;
164	        }
165	        if (owner.getRegistrationDate() != null
166	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
167	            return HttpStatus.BAD_REQUEST;
168	        }
169	        LocalDate effectiveDate = owner.getRegistrationDate() != null
170	            ? owner.getRegistrationDate() : LocalDate.now();
171	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
172	        return null;
173	    }
174	
175	    /**
176	     * Assign the owner its household link. An owner that declares it shares a household
177	     * ({@code sharesHousehold}) is given the {@link #householdId(Owner) householdId} it shares with
178	     * the other members of its household; an owner that does not declare it keeps no household. The
179	     * link is assigned before the {@link #checkForConflicts(Owner) conflict checks} because it is
180	     * part of the owner's {@link Owner#getIdentityKey() identity} and feeds its
181	     * {@link #householdSize(String) household size}.
182	     */
183	    private void assignHousehold(Owner owner, boolean sharesHousehold) {
184	        if (sharesHousehold) {
185	            owner.setHouseholdId(householdId(owner));
186	        }
187	    }
188	
189	    /**
190	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
191	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
192	     * {@link #isDuplicate(Owner) duplicates} an existing owner's identity or when its
193	     * {@link #isCityAtCapacity(String) city is already at capacity}. Returns {@code null} when the
194	     * owner clashes with nothing and may be created.
195	     */
196	    private HttpStatus checkForConflicts(Owner owner) {
197	        if (isDuplicate(owner)) {
198	            return HttpStatus.CONFLICT;
199	        }
200	        if (isCityAtCapacity(owner.getCity())) {
201	            return HttpStatus.CONFLICT;
202	        }
203	        return null;
204	    }
205	
206	    /**
207	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
208	     * {@code Location} header pointing at {@code /api/owners/{id}}.
209	     */
210	    private ResponseEntity<OwnerDto> created(Owner owner) {
211	        HttpHeaders headers = new HttpHeaders();
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
215	    }
216	
217	    /**
218	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
219	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
220	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
221	     * householdSize}. Each is computed from the owner's own fields together with the owners already
222	     * present, so this runs after the owner has been validated and has passed the duplicate and
223	     * capacity checks, and immediately before it is persisted.
224	     */
225	    private void assignDerivedAttributes(Owner owner) {
226	        owner.setCustomerCode(customerCode(owner));
227	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
228	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
229	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
230	        assignPossibleDuplicate(owner);
231	    }
232	
233	    /**
234	     * Flag a newly created owner as a possible (soft) duplicate. Because this runs after the hard
235	     * {@link #isDuplicate(Owner) duplicate} check, the owner is not an exact identity match; it is a
236	     * soft match of an existing owner as determined by {@link #findSoftDuplicate(Owner)}. When such
237	     * an owner exists the new owner is flagged with {@code possibleDuplicate = true} and
238	     * {@code possibleDuplicateOf} set to that owner's id; otherwise {@code possibleDuplicate = false}
239	     * and no matching id is recorded.
240	     */
241	    private void assignPossibleDuplicate(Owner owner) {
242	        Owner match = findSoftDuplicate(owner);
243	        owner.setPossibleDuplicate(match != null);
244	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
245	    }
246	
247	    /**
248	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
249	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
250	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
251	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
252	     * postcode never matches.
253	     */
254	    private Owner findSoftDuplicate(Owner owner) {
255	        if (owner.getPostcode() == null) {
256	            return null;
257	        }
258	        String candidateLastName = normalizeName(owner.getLastName());
259	        return this.clinicService.findAllOwners().stream()
260	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
261	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
262	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
263	            .min(Comparator.comparingInt(Owner::getId))
264	            .orElse(null);
265	    }
266	
267	    /**
268	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
269	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
270	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
271	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
272	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
273	     * every value built from the customer code (the membership number and its check digit) and the
274	     * owner's locality are derived from it.
275	     */
276	    private String customerCode(Owner owner) {
277	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
278	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
279	        return region + "-" + hash8;
280	    }
281	
282	    /**
283	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
284	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
285	     * (business-day) registration date of the owner being created, so owners are counted per
286	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
287	     */
288	    private boolean isDailyLimitReached(LocalDate day) {
289	        long count = this.clinicService.findAllOwners().stream()
290	            .filter(existing -> day.equals(existing.getRegistrationDate()))
291	            .count();
292	        return count >= 100;
293	    }
294	
295	    /**
296	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
297	     * more than 80 owners have already been created for the given business day. Counts the owners
298	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
299	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
300	     * warning.
301	     */
302	    private boolean isBulkSignup(LocalDate day) {
303	        long count = this.clinicService.findAllOwners().stream()
304	            .filter(existing -> day.equals(existing.getRegistrationDate()))
305	            .count();
306	        return count > 80;
307	    }
308	
309	    /**
310	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
311	     * advance it to the following Monday; a weekday is returned unchanged.
312	     */
313	    private LocalDate toBusinessDay(LocalDate date) {
314	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
315	            date = date.plusDays(1);
316	        }
317	        return date;
318	    }
319	
320	    /**
321	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
322	     * more owners. Cities are compared case-insensitively.
323	     */
324	    private boolean isCityAtCapacity(String city) {
325	        long count = this.clinicService.findAllOwners().stream()
326	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
327	            .count();
328	        return count >= 50;
329	    }
330	
331	    /**
332	     * The number of existing owners that already share the given firstName and lastName,
333	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
334	     * whitespace runs collapsed). Counted over the owners present before this create.
335	     */
336	    private int namesakeCount(String firstName, String lastName) {
337	        String candidateFirstName = normalizeName(firstName);
338	        String candidateLastName = normalizeName(lastName);
339	        return (int) this.clinicService.findAllOwners().stream()
340	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
341	                && normalizeName(existing.getLastName()).equals(candidateLastName))
342	            .count();
343	    }
344	
345	    /**
346	     * The number of members in this owner's household after this create: the count of existing
347	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
348	     * created. An owner with no household ({@code householdId == null}) is a household of one.
349	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
350	     * does not depend on the order in which household members were created.
351	     */
352	    private int householdSize(String householdId) {
353	        if (householdId == null) {
354	            return 1;
355	        }
356	        long existing = this.clinicService.findAllOwners().stream()
357	            .filter(other -> householdId.equals(other.getHouseholdId()))
358	            .count();
359	        return (int) existing + 1;
360	    }
361	
362	    /**
363	     * The number of national (subscriber) digits required for each known country calling
364	     * code, keyed by the code's digits (without the leading '+'). A number whose country
365	     * code appears here must carry exactly this many digits after the code, e.g. '+61'
366	     * requires 9 national digits and '+1' requires 10.
367	     */
368	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
369	        "1", 10,
370	        "61", 9);
371	
372	    /**
373	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
374	     * cannot form a valid E.164 number.
375	     *
376	     * <p>A leading '+' and country code are kept when present; otherwise country code
377	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
378	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
379	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
380	     * exactly the national-digit count that code requires (see
381	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
382	     */
383	    private String toE164(String telephone) {
384	        if (telephone == null) {
385	            return null;
386	        }
387	        boolean hasCountryCode = telephone.trim().startsWith("+");
388	        String digits = telephone.replaceAll("\\D", "");
389	        String e164;
390	        if (hasCountryCode) {
391	            e164 = digits;
392	        } else {
393	            if (digits.startsWith("0")) {
394	                digits = digits.substring(1);
395	            }
396	            e164 = "61" + digits;
397	        }
398	        if (e164.length() < 8 || e164.length() > 15) {
399	            return null;
400	        }
401	        if (!hasValidNationalLength(e164)) {
402	            return null;
403	        }
404	        return "+" + e164;
405	    }
406	
407	    /**
408	     * Whether the E.164 digit string (no leading '+') carries the national-number length
409	     * required by its country calling code. The longest matching known code wins; a number
410	     * whose country code is not recognised passes this check (its length is governed only by
411	     * the general 8-15 digit bound in {@link #toE164}).
412	     */
413	    private boolean hasValidNationalLength(String e164) {
414	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
415	            .filter(entry -> e164.startsWith(entry.getKey()))
416	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
417	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
418	            .orElse(true);
419	    }
420	
421	    /**
422	     * Whether the candidate owner duplicates an owner that already exists, and so must be
423	     * rejected with {@code 409 Conflict}. All duplicate detection is consolidated into a single
424	     * derived {@link Owner#getIdentityKey() identityKey} — the normalized telephone, email (or
425	     * empty) and householdId (or empty) joined with {@code '|'} — and an owner is a duplicate only
426	     * when its WHOLE identity key equals that of an existing owner. Because the telephone is part
427	     * of the key, two members of the same household with different telephones have different
428	     * identity keys and are both allowed; only an exact full-key match is a duplicate.
429	     */
430	    private boolean isDuplicate(Owner owner) {
431	        String identityKey = owner.getIdentityKey();
432	        return this.clinicService.findAllOwners().stream()
433	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
434	    }
435	
436	    /**
437	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
438	     * to a single space and lower-case. A null value normalizes to the empty string.
439	     */
440	    private String normalizeName(String value) {
441	        if (value == null) {
442	            return "";
443	        }
444	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
445	    }
446	
447	    /**
448	     * A stable shared identifier for the household an owner belongs to, derived deterministically
449	     * from its lastName and address. Both are normalized (case-insensitive, whitespace-collapsed)
450	     * before hashing, so every owner sharing the same household is assigned the same value
451	     * regardless of the order in which they are created. Formatted as the first 12 upper-case hex
452	     * characters of the SHA-256 of {@code '<lastName>|<address>'}.
453	     */
454	    private String householdId(Owner owner) {
455	        String key = normalizeName(owner.getLastName()) + "|" + addressNormalizer.normalize(owner.getAddress());
456	        return shaHexUpper(key).substring(0, 12);
457	    }
458	
459	    /**
460	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
461	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
462	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
463	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
464	     * {@link #customerCode} keeps the first 8).
465	     */
466	    private String shaHexUpper(String input) {
467	        try {
468	            byte[] digest = MessageDigest.getInstance("SHA-256")
469	                .digest(input.getBytes(StandardCharsets.UTF_8));
470	            StringBuilder sb = new StringBuilder(digest.length * 2);
471	            for (byte b : digest) {
472	                sb.append(String.format("%02x", b));
473	            }
474	            return sb.toString().toUpperCase();
475	        }
476	        catch (NoSuchAlgorithmException e) {
477	            throw new IllegalStateException("SHA-256 not available", e);
478	        }
479	    }
480	
481	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
482	    @Override
483	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
484	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
485	        if (currentOwner == null) {
486	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
487	        }
488	        currentOwner.setAddress(ownerFieldsDto.getAddress());
489	        currentOwner.setCity(ownerFieldsDto.getCity());
490	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
491	        currentOwner.setLastName(ownerFieldsDto.getLastName());
492	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
493	        this.clinicService.saveOwner(currentOwner);
494	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
495	    }
496	
497	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
498	    @Transactional
499	    @Override
500	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
501	        Owner owner = this.clinicService.findOwnerById(ownerId);
502	        if (owner == null) {
503	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
504	        }
505	        this.clinicService.deleteOwner(owner);
506	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
507	    }
508	
509	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
510	    @Override
511	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
512	        Owner owner = this.clinicService.findOwnerById(ownerId);
513	        if (owner == null) {
514	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
515	        }
516	        HttpHeaders headers = new HttpHeaders();
517	        Pet pet = petMapper.toPet(petFieldsDto);
518	        owner.setId(ownerId);
519	        pet.setOwner(owner);
520	        pet.getType().setName(null);
521	        this.clinicService.savePet(pet);
522	        PetDto petDto = petMapper.toPetDto(pet);
523	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
524	            .buildAndExpand(pet.getId()).toUri());
525	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
526	    }
527	
528	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
529	    @Override
530	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
531	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
532	        if (currentOwner != null) {
533	            Pet currentPet = this.clinicService.findPetById(petId);
534	            if (currentPet != null) {
535	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
536	                currentPet.setName(petFieldsDto.getName());
537	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
538	                this.clinicService.savePet(currentPet);
539	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
540	            }
541	        }
542	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
